static void paint(struct window*w){int width=w->width+32,height=w->height+32,size=width*height*4;int fd=memfd_create("window-peer",MFD_CLOEXEC);assert(fd>=0&&ftruncate(fd,size)==0);unsigned*p=mmap(NULL,size,PROT_READ|PROT_WRITE,MAP_SHARED,fd,0);assert(p!=MAP_FAILED);for(int i=0;i<width*height;i++)p[i]=w==&parent?0xff20c040:0xffc04020;struct wl_shm_pool*pool=wl_shm_create_pool(shm,fd,size);struct wl_buffer*b=wl_shm_pool_create_buffer(pool,0,width,height,width*4,WL_SHM_FORMAT_XRGB8888);wl_buffer_add_listener(b,&bl,NULL);wl_shm_pool_destroy(pool);munmap(p,size);close(fd);xdg_surface_set_window_geometry(w->xdg,16,16,w->width,w->height);wl_surface_attach(w->surface,b,0,0);wl_surface_damage(w->surface,0,0,width,height);wl_surface_commit(w->surface);}
