static void enter(void*d,struct wl_pointer*p,uint32_t s,struct wl_surface*w,wl_fixed_t x,wl_fixed_t y){(void)d;(void)p;(void)s;(void)x;(void)y;pointed=w;struct window*win=w?wl_surface_get_user_data(w):NULL;if(win)printf("pointer-enter %s\n",win->name);}static void leave(void*d,struct wl_pointer*p,uint32_t s,struct wl_surface*w){(void)d;(void)p;(void)s;(void)w;pointed=NULL;}static void motion(void*d,struct wl_pointer*p,uint32_t t,wl_fixed_t x,wl_fixed_t y){(void)d;(void)p;(void)t;(void)x;(void)y;}
static void button(void*d,struct wl_pointer*p,uint32_t serial,uint32_t t,uint32_t b,uint32_t state){(void)d;(void)p;(void)t;(void)b;printf("pointer-button %u gesture=%d pointed=%d\n",state,gesture,pointed!=NULL);if(state==WL_POINTER_BUTTON_STATE_PRESSED&&pointed&&gesture){struct window*w=wl_surface_get_user_data(pointed);if(gesture=='v')xdg_toplevel_move(w->top,seat,serial);else xdg_toplevel_resize(w->top,seat,serial,XDG_TOPLEVEL_RESIZE_EDGE_BOTTOM_RIGHT);printf("gesture %c %u\n",gesture,serial);gesture=0;}}
static void axis(void*d,struct wl_pointer*p,uint32_t t,uint32_t a,wl_fixed_t v){(void)d;(void)p;(void)t;(void)a;(void)v;}static const struct wl_pointer_listener pl={.enter=enter,.leave=leave,.motion=motion,.button=button,.axis=axis};
static void keymap(void*d,struct wl_keyboard*k,uint32_t f,int fd,uint32_t size){(void)d;(void)k;(void)f;(void)size;close(fd);}static void keyenter(void*d,struct wl_keyboard*k,uint32_t s,struct wl_surface*w,struct wl_array*a){(void)d;(void)k;(void)s;(void)a;struct window*win=w?wl_surface_get_user_data(w):NULL;if(win)printf("focus %s\n",win->name);}static void keyleave(void*d,struct wl_keyboard*k,uint32_t s,struct wl_surface*w){(void)d;(void)k;(void)s;struct window*win=w?wl_surface_get_user_data(w):NULL;if(win)printf("blur %s\n",win->name);else puts("blur destroyed");}static void key(void*d,struct wl_keyboard*k,uint32_t s,uint32_t t,uint32_t c,uint32_t state){(void)d;(void)k;(void)s;(void)t;(void)c;(void)state;}static void mods(void*d,struct wl_keyboard*k,uint32_t s,uint32_t a,uint32_t b,uint32_t c,uint32_t g){(void)d;(void)k;(void)s;(void)a;(void)b;(void)c;(void)g;}static void repeat(void*d,struct wl_keyboard*k,int32_t r,int32_t n){(void)d;(void)k;(void)r;(void)n;}static const struct wl_keyboard_listener kl={keymap,keyenter,keyleave,key,mods,repeat};
static void seatcaps(void*d,struct wl_seat*s,uint32_t caps){(void)d;if(caps&WL_SEAT_CAPABILITY_POINTER)wl_pointer_add_listener(wl_seat_get_pointer(s),&pl,NULL);if(caps&WL_SEAT_CAPABILITY_KEYBOARD)wl_keyboard_add_listener(wl_seat_get_keyboard(s),&kl,NULL);}static void seatname(void*d,struct wl_seat*s,const char*n){(void)d;(void)s;(void)n;}static const struct wl_seat_listener se={seatcaps,seatname};
static void global(void*d,struct wl_registry*r,uint32_t id,const char*n,uint32_t v){(void)d;if(!strcmp(n,"wl_compositor"))compositor=wl_registry_bind(r,id,&wl_compositor_interface,v<4?v:4);else if(!strcmp(n,"wl_shm"))shm=wl_registry_bind(r,id,&wl_shm_interface,1);else if(!strcmp(n,"xdg_wm_base")){shell=wl_registry_bind(r,id,&xdg_wm_base_interface,v<3?v:3);xdg_wm_base_add_listener(shell,&shl,NULL);}else if(!strcmp(n,"wl_seat")){seat=wl_registry_bind(r,id,&wl_seat_interface,1);wl_seat_add_listener(seat,&se,NULL);}}static void removed(void*d,struct wl_registry*r,uint32_t id){(void)d;(void)r;(void)id;}static const struct wl_registry_listener rl={global,removed};
int main(void){setbuf(stdout,NULL);display=wl_display_connect(NULL);assert(display);struct wl_registry*r=wl_display_get_registry(display);wl_registry_add_listener(r,&rl,NULL);assert(wl_display_roundtrip(display)>=0&&compositor&&shm&&shell&&seat);create(&parent,"parent");while(!done){while(wl_display_prepare_read(display)!=0)assert(wl_display_dispatch_pending(display)>=0);assert(wl_display_flush(display)>=0);struct pollfd fds[2]={{wl_display_get_fd(display),POLLIN,0},{0,POLLIN,0}};assert(poll(fds,2,30000)>0);if(fds[0].revents&POLLIN)assert(wl_display_read_events(display)>=0);else wl_display_cancel_read(display);assert(wl_display_dispatch_pending(display)>=0);if(fds[1].revents&POLLIN){char c;assert(read(0,&c,1)==1);printf("command %c\n",c);switch(c){case 'm':xdg_toplevel_set_maximized(parent.top);break;case 'n':xdg_toplevel_unset_maximized(parent.top);break;case 'f':xdg_toplevel_set_max_size(parent.top,0,0);xdg_toplevel_set_fullscreen(parent.top,NULL);break;case 'u':xdg_toplevel_set_max_size(parent.top,640,480);xdg_toplevel_unset_fullscreen(parent.top);break;case 'i':xdg_toplevel_set_minimized(parent.top);break;case 'c':create(&child,"child");break;case 'd':xdg_toplevel_set_parent(child.top,NULL);break;case 'x':destroy(&child);break;case 'v':case 'r':gesture=c;break;case 's':parent.width=parent.floating_width=300;parent.height=parent.floating_height=200;paint(&parent);break;case 'q':done=1;break;default:break;}}}destroy(&child);destroy(&parent);wl_display_flush(display);wl_display_disconnect(display);puts("window-done");return 0;}
